from sys import stdin, stdout
import math

MOD = 10**9 + 7

def nCr(n, r):
    if r > n:
        return 0
    return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

def solve(N, K):
    dp = [0] * (K + 1)
    dp[0] = 1

    for i in range(1, N + 1):
        new_dp = [0] * (K + 1)
        for j in range(K + 1):
            if j == 0:
                new_dp[j] = dp[j]
            else:
                new_dp[j] = (dp[j] + dp[j - 1]) % MOD
        dp = new_dp

    result = [0] * K
    for i in range(1, K + 1):
        result[i - 1] = (nCr(N - 1, i - 1) * dp[K - i]) % MOD

    return result

# Read input
N, K = map(int, stdin.readline().split())

# Solve the problem
result = solve(N, K)

# Print the result
for num in result:
    stdout.write(f"{num}\n")
